def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 3:
        return 'C'

    last_mine, last_opp = history[-1]

    opp_d = 0
    start10 = n - 10 if n > 10 else 0
    start20 = n - 20 if n > 20 else 0
    recent10_c = 0
    recent20_c = 0

    for i in range(n):
        if history[i][1] == 'D':
            opp_d += 1
        else:
            if i >= start10:
                recent10_c += 1
            if i >= start20:
                recent20_c += 1

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    my_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_d_streak += 1
        else:
            break

    reward = 0
    punish = 0
    start_t = n - 12 if n > 12 else 0
    for i in range(start_t, n - 1):
        if history[i][0] == 'D':
            if history[i + 1][1] == 'C':
                reward += 1
            else:
                punish += 1

    remaining = 100 - n
    if remaining <= 1:
        return 'D'

    if last_opp == 'D':
        if recent20_c == 0 and n >= 20:
            return 'D'

        if recent10_c == 0:
            if 4 <= opp_d_streak <= 6:
                return 'C'
            if opp_d_streak >= 8 and my_d_streak >= 5:
                return 'C'
            return 'D'

        if opp_d_streak == 1:
            if last_mine == 'D':
                return 'C'
            if history[-2][0] == 'D' and history[-2][1] == 'C':
                return 'C'
            return 'D'

        if opp_d_streak >= 5:
            if last_mine == 'D' and my_d_streak >= 3:
                return 'C'
            if recent10_c >= 4:
                return 'C'
            if my_d_streak >= 4:
                return 'C'
            return 'D'

        if opp_d_streak >= 3:
            if my_d_streak >= 3:
                return 'C'
            if opp_d_streak == 4 and recent10_c >= 6 and last_mine == 'C':
                return 'C'
            return 'D'

        return 'D'

    if reward >= 1 and punish == 0 and recent10_c >= 8 and opp_d * 4 <= n:
        return 'D'

    if punish == 0 and recent10_c >= 9 and n >= 12 and remaining > 3 and last_mine != 'D':
        if rng.random() < 0.05:
            return 'D'
        if opp_d == 0 and (n == 15 or n == 28 or n == 41 or n == 54 or n == 67 or n == 80):
            return 'D'

    return 'C'

