def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_c = 0
    opp_d = 0
    my_c = 0
    my_d = 0
    for i in range(n):
        a = history[i][0]
        b = history[i][1]
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if a == 'C':
            my_c += 1
        else:
            my_d += 1

    last_m = history[-1][0]
    last_o = history[-1][1]
    rate = opp_c / float(n)

    if n == 99:
        return 'D'

    if n == 1:
        if last_o == 'D':
            return 'D'
        return 'C'

    if n < 8:
        if last_o == 'C':
            if my_d > 0:
                if rng.random() < 0.45:
                    return 'D'
                return 'C'
            return 'C'
        else:
            if opp_c == 0:
                if n % 2 == 0:
                    return 'C'
                return 'D'
            d_streak = 0
            for i in range(n - 1, -1, -1):
                if history[i][1] == 'D':
                    d_streak += 1
                else:
                    break
            if d_streak == 1:
                return 'D'
            if d_streak <= 3 and (rate > 0.4 or opp_c > 1):
                return 'C'
            return 'D'

    if opp_c == 0:
        return 'D'

    if opp_d == 0:
        if n < 10:
            return 'C'
        if my_d > 0:
            if rng.random() < 0.94:
                return 'D'
            return 'C'
        pr = 0.05 + min(0.35, (n - 10) * 0.005)
        if n >= 80:
            pr = 0.75
        if rng.random() < pr:
            return 'D'
        return 'C'

    recent5_c = 0
    start = n - 5
    if start < 0:
        start = 0
    for i in range(start, n):
        if history[i][1] == 'C':
            recent5_c += 1

    recent10_c = 0
    start = n - 10
    if start < 0:
        start = 0
    for i in range(start, n):
        if history[i][1] == 'C':
            recent10_c += 1

    recent20_c = 0
    start = n - 20
    if start < 0:
        start = 0
    for i in range(start, n):
        if history[i][1] == 'C':
            recent20_c += 1

    d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            d_streak += 1
        else:
            break

    trans = [[0, 0], [0, 0], [0, 0], [0, 0]]
    row_counts = [[0, 0], [0, 0]]
    col_counts = [[0, 0], [0, 0]]
    forgive = 0
    punish = 0

    for i in range(1, n):
        pm = history[i - 1][0]
        po = history[i - 1][1]
        co = history[i][1]
        mbit = 0 if pm == 'C' else 1
        obit = 0 if po == 'C' else 1
        s = mbit * 2 + obit
        co_bit = 0 if co == 'C' else 1
        trans[s][co_bit] += 1
        row_counts[mbit][co_bit] += 1
        col_counts[obit][co_bit] += 1
        if mbit == 1:
            if co_bit == 0:
                forgive += 1
            else:
                punish += 1

    if rate < 0.18 and (recent10_c <= 1 or d_streak >= 4):
        return 'D'
    if rate < 0.30 and recent10_c <= 2 and d_streak >= 5:
        return 'D'

    if last_o == 'D':
        if d_streak >= 5:
            return 'D'
        if rate >= 0.40 and recent20_c >= 7:
            if d_streak == 2 or d_streak == 3:
                return 'C'
            if d_streak >= 4:
                return 'D'
        if d_streak == 1 and rate >= 0.80 and recent20_c >= 12 and my_c >= 0.80 * n:
            return 'C'

    R = 100 - n
    if R <= 0:
        return 'D'

    prior_base = 0.5 + 0.35 * (rate - 0.5)
    if prior_base < 0.20:
        prior_base = 0.20
    elif prior_base > 0.80:
        prior_base = 0.80

    pvals = [0.0, 0.0, 0.0, 0.0]
    for s in range(4):
        obs_c = trans[s][0]
        tot = obs_c + trans[s][1]
        m = s // 2
        o = s % 2
        row_tot = row_counts[m][0] + row_counts[m][1]
        col_tot = col_counts[o][0] + col_counts[o][1]
        if row_tot >= 5:
            row_p = row_counts[m][0] / float(row_tot)
        else:
            row_p = prior_base
        if col_tot >= 5:
            col_p = col_counts[o][0] / float(col_tot)
        else:
            col_p = prior_base
        state_prior = (row_p + col_p + prior_base) / 3.0
        if tot >= 8:
            p = obs_c / float(tot)
        elif tot >= 3:
            p = (obs_c + 4.0 * state_prior) / (float(tot) + 4.0)
        else:
            p = (obs_c + 3.0 * state_prior) / (float(tot) + 3.0)
        if p < 0.03:
            p = 0.03
        elif p > 0.97:
            p = 0.97
        pvals[s] = p

    V = [0.0, 0.0, 0.0, 0.0]
    for _ in range(R - 1):
        NV = [0.0, 0.0, 0.0, 0.0]
        for s in range(4):
            p = pvals[s]
            q = 1.0 - p
            vc = 3.0 * p + p * V[0] + q * V[1]
            vd = 5.0 * p + 1.0 * q + p * V[2] + q * V[3]
            if vd > vc:
                NV[s] = vd
            else:
                NV[s] = vc
        V = NV

    mbit = 0 if last_m == 'C' else 1
    obit = 0 if last_o == 'C' else 1
    s = mbit * 2 + obit
    p = pvals[s]
    q = 1.0 - p
    vc = 3.0 * p + p * V[0] + q * V[1]
    vd = 5.0 * p + 1.0 * q + p * V[2] + q * V[3]

    if vd > vc:
        return 'D'

    if last_o == 'C' and forgive >= 2 and forgive > punish and rate > 0.50:
        pr = 0.25 + 0.35 * (forgive / float(forgive + punish + 1))
        if n >= 75:
            pr += 0.15
        if pr > 0.75:
            pr = 0.75
        if rng.random() < pr:
            return 'D'

    return 'C'

