        if a == 'D' and b == 'C':
            same_d_c += 1
        if a == 'C' and b == 'D':
            opp_d_my_c += 1

    opp_d = n - opp_c
    my_c = n - my_d
    opp_rate = opp_c / n
    last_me = me[-1]
    last_op = op[-1]
    prev_me = me[-2] if n >= 2 else 'C'

    recent_len = min(10, n)
    recent_d = 0
    for i in range(n - recent_len, n):
        if op[i] == 'D':
            recent_d += 1
    recent_c = recent_len - recent_d

    d_next_c = 0
    d_next_d = 0
    for i in range(n - 1):
        if me[i] == 'D':
            if op[i + 1] == 'C':
                d_next_c += 1
            else:
                d_next_d += 1

    recent_start = max(0, n - 25)
    recent_d_next_c = 0
    recent_d_next_d = 0
    recent_same_d_c = 0
    recent_opp_d_my_c = 0
