def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [None] * n
    op = [None] * n
    total_d = 0
    for i in range(n):
        a, b = history[i]
        my[i] = a
        op[i] = b
        if b == 'D':
            total_d += 1
    total_c = n - total_d

    d_streak = 0
    i = n - 1
    while i >= 0 and op[i] == 'D':
        d_streak += 1
        i -= 1

    c_before = 0
    while i >= 0 and op[i] == 'C':
        c_before += 1
        i -= 1

    w = 8
    if n < w:
        w = n
    recent_d = 0
    start_recent = n - w
    for k in range(start_recent, n):
        if op[k] == 'D':
            recent_d += 1
    recent_c = w - recent_d

    start_streak = n - d_streak
    my_c_in_streak = 0
    for k in range(start_streak, n):
        if my[k] == 'C':
            my_c_in_streak += 1

    d_to_c = 0
    d_to_d = 0
    trans_from = 1
    if n > 13:
        trans_from = n - 12
    for k in range(trans_from, n):
        if my[k - 1] == 'D':
            if op[k] == 'C':
                d_to_c += 1
            else:
                d_to_d += 1

    last_o = op[n - 1]

    if last_o == 'D':
        if total_c >= 1:
            if recent_c >= 4 or total_c * 3 >= n * 2:
                max_attempts = 4
            elif recent_c >= 2 or total_c >= 3:
                max_attempts = 2
            else:
                max_attempts = 2

            if recent_d >= 6 and d_to_c == 0:
                max_attempts = 1

            need_forgive = False
            if d_streak <= 6 and my_c_in_streak < max_attempts:
                if my_c_in_streak > 0:
                    need_forgive = True
                elif d_streak >= 2 and n >= 2 and my[-2] == 'C' and recent_c >= 2:
                    need_forgive = True
                elif c_before >= 5 and d_streak <= 4:
                    need_forgive = True

            if need_forgive:
                return 'C'

            if (
                c_before >= 8
                and d_streak <= 12
                and my_c_in_streak >= max_attempts
                and rng.random() < 0.08
            ):
                return 'C'

        return 'D'

    if d_to_c > d_to_d and recent_c >= 2:
        return 'D'

    if total_c * 5 >= n * 4 and recent_c * 2 >= recent_d:
        return 'C'

    if total_d * 2 > n and recent_d > recent_c:
        return 'D'

    return 'C'

