def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_opp = history[-1]

    opp_c = 0
    my_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1
    opp_rate = opp_c / float(n)

    recent_start = n - 10
    if recent_start < 0:
        recent_start = 0
    recent_opp_c = 0
    recent_len = 0
    i = recent_start
    while i < n:
        recent_len += 1
        if history[i][1] == 'C':
            recent_opp_c += 1
        i += 1
    recent_opp_d = recent_len - recent_opp_c

    streak_d = 0
    my_d_in_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        streak_d += 1
        if history[i][0] == 'D':
            my_d_in_streak += 1
        i -= 1

    if n >= 8 and opp_c <= 2:
        return 'D'
    if n >= 15 and recent_opp_d >= 9:
        return 'D'
    if n >= 20 and opp_rate < 0.25:
        return 'D'

    rc = [0, 0, 0, 0]
    rd = [0, 0, 0, 0]
    raw_all_f = 0
    raw_all_p = 0
    raw_str_f = 0
    raw_str_p = 0

    start_recent = n - 30
    if start_recent < 1:
        start_recent = 1

    i = 1
    while i < n:
        pm, po = history[i - 1]
        co = history[i][1]

        if pm == 'C':
            s = 0 if po == 'C' else 1
        else:
            s = 2 if po == 'C' else 3

        if s >= 2:
            if co == 'C':
                raw_all_f += 1
            else:
                raw_all_p += 1
            if s == 2:
                if co == 'C':
                    raw_str_f += 1
                else:
                    raw_str_p += 1

        w = 1
        if i >= start_recent:
            w = 2

        if co == 'C':
            rc[s] += w
        else:
            rd[s] += w

        i += 1

    evidence = raw_all_f + raw_all_p

    pc = [4, 3, 1, 1]
    pd = [1, 2, 7, 8]
    q = [0.0, 0.0, 0.0, 0.0]
    i = 0
    while i < 4:
        num = pc[i] + rc[i]
        den = num + pd[i] + rd[i]
        val = num / float(den)
        if val < 0.02:
            val = 0.02
        elif val > 0.98:
            val = 0.98
        q[i] = val
        i += 1

    if last_my == 'C':
        state = 0 if last_opp == 'C' else 1
    else:
        state = 2 if last_opp == 'C' else 3

    rem = 100 - n
    v = [0.0, 0.0, 0.0, 0.0]
    step = 1
    while step < rem:
        nv = [0.0, 0.0, 0.0, 0.0]
        i = 0
        while i < 4:
            qq = q[i]
            oq = 1.0 - qq
            cv = 3.0 * qq + qq * v[0] + oq * v[1]
            dv = 1.0 + 4.0 * qq + qq * v[2] + oq * v[3]
            nv[i] = cv if cv >= dv else dv
            i += 1
        v = nv
        step += 1

    qq = q[state]
    oq = 1.0 - qq
    cv = 3.0 * qq + qq * v[0] + oq * v[1]
    dv = 1.0 + 4.0 * qq + qq * v[2] + oq * v[3]
    dp_action = 'D' if dv > cv else 'C'

    if n < 85:
        if last_my == 'D' and last_opp == 'D':
            if opp_rate > 0.55 and streak_d <= 4 and my_d_in_streak >= 1:
                return 'C'
            if opp_rate > 0.65 and recent_opp_c >= 8 and streak_d <= 3:
                return 'C'
            return 'D'

        if last_my == 'C' and last_opp == 'D':
            if n >= 2 and history[-2][0] == 'D' and opp_rate > 0.55 and streak_d <= 4:
                return 'C'
            if streak_d >= 5:
                return 'D'
            if recent_opp_d >= 6:
                return 'D'
            return 'D'

        if last_my == 'D' and last_opp == 'C':
            if evidence == 0 and opp_rate > 0.45:
                return 'C'
            if raw_str_f <= raw_str_p and raw_all_p >= raw_all_f and opp_rate > 0.55 and recent_opp_c >= 7:
                return 'C'

        if last_my == 'C' and last_opp == 'C':
            if 20 <= n <= 80 and opp_rate > 0.6 and recent_opp_c >= 7:
                if evidence == 0:
                    return 'D'
                if raw_str_f == 1 and raw_str_p == 0 and opp_rate > 0.75 and recent_opp_c >= 8:
                    return 'D'
            return dp_action

    return dp_action

