def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'
    my_last, opp_last = history[-1]
    if n < 5:
        return 'C'
    if n == 99:
        return 'D'

    opp_c = 0
    pC_myC = 0
    pTot_myC = 0
    pC_myD = 0
    pTot_myD = 0
    rC_myC = 0
    rTot_myC = 0
    rC_myD = 0
    rTot_myD = 0

    for i in range(n):
        m, o = history[i]
        if o == 'C':
            opp_c += 1
        if i > 0:
            pm = history[i - 1][0]
            if pm == 'C':
                pTot_myC += 1
                if o == 'C':
                    pC_myC += 1
            else:
                pTot_myD += 1
                if o == 'C':
                    pC_myD += 1
        if i + 1 < n:
            mm = history[i][0]
            oo = history[i + 1][1]
            if mm == 'C':
                rTot_myC += 1
                if oo == 'C':
                    rC_myC += 1
            else:
                rTot_myD += 1
                if oo == 'C':
                    rC_myD += 1

    recent10_c = 0
    recent10_my_c = 0
    st = n - 10
    if st < 0:
        st = 0
    for i in range(st, n):
        if history[i][1] == 'C':
            recent10_c += 1
        if history[i][0] == 'C':
            recent10_my_c += 1

    trailD = 0
    if opp_last == 'D':
        i = n - 1
        while i >= 0:
            if history[i][1] == 'D':
                trailD += 1
                i -= 1
            else:
                break

    trailC = 0
    if opp_last == 'C':
        i = n - 1
        while i >= 0:
            if history[i][1] == 'C':
                trailC += 1
                i -= 1
            else:
                break

    opp_rate = float(opp_c) / float(n)
    recent10_len = min(10, n)
    recent10_rate = float(recent10_c) / float(recent10_len)

    if trailD >= 5:
        if opp_rate > 0.80 and recent10_c >= 7 and rng.random() < 0.12:
            return 'C'
        return 'D'

    if trailD >= 1:
        if opp_rate < 0.28 or recent10_c <= 2:
            return 'D'
        if opp_rate <= 0.66 and recent10_c <= 7 and recent10_my_c >= 4:
            return 'D'
        return 'C'

    if rTot_myD > 0 and rC_myD == rTot_myD and recent10_c >= 8:
        return 'D'

    if opp_rate <= 0.66 and recent10_c <= 7 and recent10_my_c >= 5:
        return 'D'

    if rTot_myD == 0 and trailC >= 10 and recent10_c >= 9 and opp_c >= n - 4:
        if opp_c == n and n >= 16:
            return 'D'
        if rng.random() < 0.07:
            return 'D'

    if pTot_myC + pTot_myD >= 6:
        if my_last == 'C':
            p = float(pC_myC + 2.0) / float(pTot_myC + 4.0)
        else:
            p = float(pC_myD + 2.0) / float(pTot_myD + 4.0)
    else:
        p = float(opp_c) / float(n)

    p = 0.55 * p + 0.25 * recent10_rate + 0.20 * opp_rate
    if p < 0.0:
        p = 0.0
    elif p > 1.0:
        p = 1.0

    qC = float(rC_myC + 2.0) / float(rTot_myC + 4.0)
    if qC > 1.0:
        qC = 1.0

    if rTot_myD == 0:
        qD = 0.25
    else:
        qD = float(rC_myD + 1.0) / float(rTot_myD + 3.0)
        if qD > 1.0:
            qD = 1.0

    rem = 100 - n - 1
    if rem <= 0:
        return 'D'

    immC = 3.0 * p
    immD = 1.0 + 4.0 * p

    if rem == 1:
        nextC = 1.0 + 4.0 * qC
        nextD = 1.0 + 4.0 * qD
    else:
        nextC = 1.0 + 2.0 * qC
        nextD = 1.0 + 2.0 * qD

    w = 1.0
    if n < 20:
        w = 0.80
    elif n > 85:
        w = 0.90

    valC = immC + rem * nextC * w
    valD = immD + rem * nextD * w

    if valD > valC + 0.2:
        return 'D'
    return 'C'

