    if opp_d == n:
        return 'D'

    if n == 99:
        return 'D'

    last_mine, last_opp = history[-1]
    prev_mine = history[-2][0]
    prev2_mine = history[-3][0]

    myD_C = 0
    myD_D = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            if history[i + 1][1] == 'C':
                myD_C += 1
            else:
                myD_D += 1

    window = 5
    if n < window:
        window = n
    start = n - window
    rec_opp_d = 0
    rec_my_d = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            rec_opp_d += 1
        if history[i][0] == 'D':
            rec_my_d += 1

    opp_d_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        opp_d_streak += 1
        i -= 1

    my_d_streak = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'D':
        my_d_streak += 1
        i -= 1

    if opp_d == 0:
        if my_d == 0:
            if n >= 12:
                return 'D'
            return 'C'
        if last_mine == 'D':
            if myD_C >= 2 or my_d >= 3:
                return 'D'
            return 'C'
        return 'D'

