                return 'D'
            if myD_C == 1 and myD_D == 0:
                if last_mine == 'D':
                    return 'C'
                return 'D'

        if my_d == 0 and opp_c >= opp_d + 10 and rec_opp_d == 0 and n >= 40:
            return 'D'

        if (n == 98 and opp_c >= opp_d + 5 and rec_opp_d == 0 and
                myD_C >= 1 and myD_D == 0):
            return 'D'

        return 'C'

    if (last_mine == 'D' and
            my_d_streak >= 3 and
            opp_d_streak >= 3 and
