    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_d = 0
    my_d = 0
    unprovoked = 0
    unprovoked5 = 0
    opp_d5 = 0
    opp_d10 = 0

    last5 = n - 5
    if last5 < 0:
        last5 = 0
    last10 = n - 10
    if last10 < 0:
        last10 = 0

    for i, pair in enumerate(history):
        m = pair[0]
        o = pair[1]
        if m == 'D':
            my_d += 1
        if o == 'D':
            opp_d += 1
            if i >= last5:
                opp_d5 += 1
            if i >= last10:
                opp_d10 += 1
            if i == 0 or history[i - 1][0] == 'C':
                unprovoked += 1
                if i >= last5:
                    unprovoked5 += 1

    opp_rate = opp_d / n

    opp_def_streak = 0
    for pair in reversed(history):
        if pair[1] == 'D':
            opp_def_streak += 1
        else:
            break

    my_def_streak = 0
    for pair in reversed(history):
        if pair[0] == 'D':
            my_def_streak += 1
        else:
            break

    before_len = n
    while before_len > 0 and history[before_len - 1][0] == 'D':
        before_len -= 1

    opp_c_before = 0
    for i in range(before_len):
        if history[i][1] == 'C':
            opp_c_before += 1

    was_pre_coop = before_len >= 8 and opp_c_before * 10 >= before_len * 7

