def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    remaining = 100 - n
    if remaining <= 0:
        return 'D'

    my_d = 0
    opp_d = 0
    for i in range(n):
        a, b = history[i]
        if a == 'D':
            my_d += 1
        if b == 'D':
            opp_d += 1

    # One early test after a clean cooperative start.
    if n == 10 and my_d == 0 and opp_d == 0:
        return 'D'

    # Immediately after the test, cooperate once to learn whether the
    # opponent punishes defection.
    if n == 11 and my_d == 1 and opp_d == 0 and history[-1] == ('D', 'C'):
        return 'C'

    # If the opponent has never defected and we already know they do not
    # punish, exploit them aggressively.
    if opp_d == 0 and my_d > 0 and n >= 12 and history[-1][1] == 'C':
        if history[-1] == ('C', 'C') or my_d > 1:
            return 'D'

    # Compact Markov state:
    # id 0       : C,C
    # id 1-3     : D,C with own defection run 1..3
    # id 4-6     : C,D with opponent defection run 1..3
    # id 7-15    : D,D with opponent run 1..3 and own run 1..3
    A = [0] * 16
    B = [0] * 16
    O = [0] * 16
    M = [0] * 16

    for m in range(1, 4):
        idx = m
        A[idx] = 1
        B[idx] = 0
        O[idx] = 0
        M[idx] = m

    for o in range(1, 4):
        idx = 4 + (o - 1)
        A[idx] = 0
        B[idx] = 1
        O[idx] = o
        M[idx] = 0

    idx = 7
    for o in range(1, 4):
        for m in range(1, 4):
            A[idx] = 1
            B[idx] = 1
            O[idx] = o
            M[idx] = m
            idx += 1

    N01 = [0] * 16
    N10 = [0] * 16
    N11 = [0] * 16

    for s in range(16):
        no = O[s] + 1
        if no > 3:
            no = 3
        nm = M[s] + 1
        if nm > 3:
            nm = 3

        # current action C, opponent D:
        N01[s] = 4 + (no - 1)

        # current action D, opponent C:
        N10[s] = nm

        # current action D, opponent D:
        N11[s] = 7 + (no - 1) * 3 + (nm - 1)

    c = [0.0] * 16
    d = [0.0] * 16

    a = 1 if history[0][0] == 'D' else 0
    b = 1 if history[0][1] == 'D' else 0
    runO = 1 if b == 1 else 0
    runM = 1 if a == 1 else 0

    for i in range(1, n):
        if b == 0:
            sid = 0 if a == 0 else runM
        else:
            if a == 0:
                sid = 4 + (runO - 1)
            else:
                sid = 7 + (runO - 1) * 3 + (runM - 1)

        age = n - i - 1
        if age < 5:
            w = 4.0
        elif age < 15:
            w = 2.0
        else:
            w = 1.0

        if history[i][1] == 'C':
            c[sid] += w
        else:
            d[sid] += w

        na = 1 if history[i][0] == 'D' else 0
        nb = 1 if history[i][1] == 'D' else 0

        if na == 1:
            runM += 1
            if runM > 3:
                runM = 3
        else:
            runM = 0

        if nb == 1:
            runO += 1
            if runO > 3:
                runO = 3
        else:
            runO = 0

        a = na
        b = nb

    if b == 0:
        current = 0 if a == 0 else runM
    else:
        if a == 0:
            current = 4 + (runO - 1)
        else:
            current = 7 + (runO - 1) * 3 + (runM - 1)

    coop = opp_d * 5 <= n
    strength = 3.0
    probs = [0.5] * 16

    for s in range(16):
        cc = c[s]
        dd = d[s]

        if B[s] == 0:
            if A[s] == 0:
                p0 = 0.95 if coop else 0.85
            else:
                p0 = 0.08 if coop else 0.04
        else:
            if A[s] == 0:
                o = O[s]
                if o == 1:
                    p0 = 0.75 if coop else 0.18
                elif o == 2:
                    p0 = 0.35 if coop else 0.08
                else:
                    p0 = 0.15 if coop else 0.04
            else:
                o = O[s]
                m = M[s]
                if coop:
                    if m <= 1 and o <= 1:
                        p0 = 0.35
                    elif m <= 2 and o <= 2:
                        p0 = 0.18
                    else:
                        p0 = 0.07
                else:
                    if m <= 1 and o <= 1:
                        p0 = 0.10
                    elif m <= 2 and o <= 2:
                        p0 = 0.04
                    else:
                        p0 = 0.02

        probs[s] = (cc + strength * p0) / (cc + dd + strength)

    vals = [0.0] * 16
    choice = 0
    pvals = probs

    for _ in range(1, remaining + 1):
        new = [0.0] * 16
        v = vals

        for s in range(16):
            p = pvals[s]
            q = 1.0 - p

            vC = p * (3.0 + v[0]) + q * v[N01[s]]
            vD = p * (5.0 + v[N10[s]]) + q * (1.0 + v[N11[s]])

            if vC >= vD:
                new[s] = vC
                if s == current:
                    choice = 0
            else:
                new[s] = vD
                if s == current:
                    choice = 1

        vals = new

    return 'C' if choice == 0 else 'D'

