    my_c = 0
    my_d = 0
    for a, b in history:
        if a == 'C':
            my_c += 1
        else:
            my_d += 1
        if b == 'C':
            opp_c += 1

    d_opp = n - opp_c
    if opp_c == 0:
        return 'D'

    coop_rate = opp_c / n

    opp_d_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        opp_d_streak += 1
        i -= 1

    my_d_streak = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'D':
        my_d_streak += 1
        i -= 1

    recent_d = 0
    rs = n - 12
    if rs < 0:
        rs = 0
    for i in range(rs, n):
        if history[i][1] == 'D':
            recent_d += 1

    attempts = 0
    my_d_in_streak = 0
    if opp_d_streak > 0:
        for i in range(n - opp_d_streak, n):
            if history[i][0] == 'C':
                attempts += 1
            else:
                my_d_in_streak += 1

    c_tot = c_to_c = 0
    d_tot = d_to_c = 0
    rc_tot = rc_c = 0
    rd_tot = rd_c = 0

    pc = {'CC': 0, 'CD': 0, 'DC': 0, 'DD': 0}
    pt = {'CC': 0, 'CD': 0, 'DC': 0, 'DD': 0}

    r_start = n - 17
    if r_start < 0:
        r_start = 0

    for i in range(n - 1):
        mine = history[i][0]
        oppc = history[i][1]
        nxt = history[i + 1][1]

        if mine == 'C':
            c_tot += 1
            if nxt == 'C':
                c_to_c += 1
        else:
            d_tot += 1
            if nxt == 'C':
                d_to_c += 1

        s = mine + oppc
        pt[s] += 1
        if nxt == 'C':
            pc[s] += 1

        if i >= r_start:
            if mine == 'C':
                rc_tot += 1
                if nxt == 'C':
                    rc_c += 1
            else:
                rd_tot += 1
                if nxt == 'C':
                    rd_c += 1

    prior_C = coop_rate
    if prior_C < 0.15:
        prior_C = 0.15
    if prior_C > 0.95:
        prior_C = 0.95

