def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'

    my = [0] * n
    op = [0] * n
    opp_c = 0
    my_d = 0
    for i in range(n):
        if history[i][0] == 'C':
            my[i] = 0
        else:
            my[i] = 1
            my_d += 1
        if history[i][1] == 'C':
            op[i] = 0
            opp_c += 1
        else:
            op[i] = 1
    opp_d = n - opp_c

    if opp_d == 0:
        if my_d == 0:
            if n == 50:
                return 'D'
            return 'C'
        if my[-1] == 1 and op[-1] == 0:
            return 'C'
        return 'D'

    if opp_c == 0:
        return 'D'

    if op[-1] == 1 and my[-1] == 0:
        run_d = 0
        for i in range(n - 1, -1, -1):
            if op[i] == 1:
                run_d += 1
            else:
                break
        if run_d >= 2:
            return 'D'

    cnt_c = [0.0, 0.0, 0.0, 0.0]
    cnt_t = [0.0, 0.0, 0.0, 0.0]
    recent_start = max(1, n - 25)
    for i in range(1, n):
        s = my[i - 1] * 2 + op[i - 1]
        w = 2.0 if i >= recent_start else 1.0
        cnt_t[s] += w
        if op[i] == 0:
            cnt_c[s] += w

    rate = opp_c / float(n)
    p0 = [
        0.55 + 0.45 * rate,
        0.50 + 0.50 * rate,
        0.05 + 0.25 * rate,
        0.15 + 0.35 * rate
    ]

    prior_w = 2.0
    prob = [0.0, 0.0, 0.0, 0.0]
    for s in range(4):
        p = (prior_w * p0[s] + cnt_c[s]) / (prior_w + cnt_t[s])
        if p < 0.02:
            p = 0.02
        if p > 0.98:
            p = 0.98
        prob[s] = p

    rem = 100 - n
    values = [0.0, 0.0, 0.0, 0.0]
    for _ in range(rem - 1):
        new = [0.0, 0.0, 0.0, 0.0]
        for s in range(4):
            pc = prob[s]
            pd = 1.0 - pc
            vc = pc * (3.0 + values[0]) + pd * (0.0 + values[1])
            vd = pc * (5.0 + values[2]) + pd * (1.0 + values[3])
            new[s] = vc if vc >= vd else vd
        values = new

    s0 = my[-1] * 2 + op[-1]
    pc = prob[s0]
    pd = 1.0 - pc
    vc = pc * (3.0 + values[0]) + pd * (0.0 + values[1])
    vd = pc * (5.0 + values[2]) + pd * (1.0 + values[3])
    return 'D' if vd > vc else 'C'

