    dc_count = 0
    punished = 0

    for i in range(n):
        m = me[i]
        o = opp[i]
        if o == 'C':
            opp_c += 1
        if m == 'D':
            my_d_total += 1
        if m == 'D' and o == 'C':
            dc_count += 1
        if i > 0 and me[i - 1] == 'D' and opp[i] == 'D':
            punished += 1

    opp_d = n - opp_c

    opp_d_streak = 0
    for x in reversed(opp):
        if x == 'D':
            opp_d_streak += 1
        else:
            break

    opp_c_streak = 0
    for x in reversed(opp):
        if x == 'C':
            opp_c_streak += 1
        else:
            break

    my_d_streak = 0
    for x in reversed(me):
        if x == 'D':
            my_d_streak += 1
        else:
            break

    unprov = 0
    start = n - 10
