    if last_me == 'D':
        if opp_d_streak >= 15 and opp_c_streak == 0 and n > 20:
            return 'D'
        if my_d_streak >= 6:
            return 'C'
        return 'D'

    if n >= 2 and me[-2] == 'D':
        attempts = 0
        for i in range(n - 1, -1, -1):
            if me[i] == 'C' and opp[i] == 'D':
                attempts += 1
