    my_d_streak = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'D':
        my_d_streak += 1
        i -= 1

    rs = n - 10
    if rs < 0:
        rs = 0
    rec_len = n - rs
    rec_c = 0
    for j in range(rs, n):
        if history[j][1] == 'C':
            rec_c += 1
    rec_rate = rec_c / rec_len

