        else:
            opp_c += 1

        if i > 0:
            prev_me = history[i - 1][0]
            if prev_me == 'D':
                if o == 'C':
                    seen_nonpunish = True
            else:
                if o == 'D':
                    cd_total += 1

    r10 = sum(1 for _, o in history[-10:] if o == 'D')
    r20 = sum(1 for _, o in history[-20:] if o == 'D')

    cd_recent = 0
    if n > 1:
        start = max(1, n - 10)
        for i in range(start, n):
            if history[i - 1][0] == 'C' and history[i][1] == 'D':
                cd_recent += 1

    opp_d_streak = 0
    if last_opp == 'D':
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                opp_d_streak += 1
            else:
                break

    opp_c_streak = 0
    if last_opp == 'C':
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'C':
                opp_c_streak += 1
            else:
                break

