def strategy(history, rng):
    n = len(history)
    if n >= 99:
        return 'D'
    if n == 0:
        return 'C'

    my = []
    op = []
    for a, b in history:
        my.append(0 if a == 'C' else 1)
        op.append(0 if b == 'C' else 1)

    if n == 1:
        return 'C' if op[0] == 0 else 'D'
    if n == 2:
        if op[0] == 1 and op[1] == 1:
            return 'D'
        return 'C'

    opp_c = 0
    for x in op:
        if x == 0:
            opp_c += 1

    opp_run_D = 0
    for x in reversed(op):
        if x == 1:
            opp_run_D += 1
        else:
            break

    # Obvious hostile opponents.
    if n >= 6 and opp_c <= 1:
        return 'D'
    if n >= 10 and opp_c * 10 < n and opp_run_D >= 6:
        return 'D'

    # If they defected twice in a row after we cooperated, they are not
    # responding like forgiving TFT; stop being exploited.
    if op[-1] == 1 and my[-1] == 0 and opp_run_D >= 2:
        return 'D'

    # Escape after a sustained mutual-D phase against short-punishment TFT.
    if opp_run_D == 4 and my[-1] == 1 and op[-1] == 1 and opp_c * 5 > n:
        return 'C'

    # Transition counts for order-1 and order-2 opponent models.
    tot1 = [0, 0, 0, 0]
    c1 = [0, 0, 0, 0]
    totMC = 0
    totMD = 0
    cMC = 0
    cMD = 0

    for i in range(1, n):
        s1 = (my[i - 1] << 1) | op[i - 1]
        tot1[s1] += 1
        if op[i] == 0:
            c1[s1] += 1

        if my[i - 1] == 0:
            totMC += 1
            if op[i] == 0:
                cMC += 1
        else:
            totMD += 1
            if op[i] == 0:
                cMD += 1

    tot2 = [0, 0, 0, 0, 0, 0, 0, 0]
    c2 = [0, 0, 0, 0, 0, 0, 0, 0]

    for i in range(2, n):
        s2 = (my[i - 1] << 2) | (op[i - 1] << 1) | op[i - 2]
        tot2[s2] += 1
        if op[i] == 0:
            c2[s2] += 1

    RW = n if n < 20 else 20
    recent_c_count = 0
    for x in op[-RW:]:
        if x == 0:
            recent_c_count += 1
    recent_c_rate = recent_c_count / float(RW)

    pcC = (cMC + 1.0) / (float(totMC) + 2.0) if totMC > 0 else 0.7
    pcD = (cMD + 1.0) / (float(totMD) + 2.0) if totMD > 0 else 0.3

    # Unresponsive/forgiving opponents can often be exploited.
    if totMD >= 3:
        if pcD >= 0.80 and recent_c_rate > 0.55:
            return 'D'
        if pcD >= 0.66 and pcD >= pcC - 0.13 and recent_c_rate > 0.35:
            return 'D'

    # Priors:
    #   0 CCC, 1 CCD, 2 CDC, 3 CDD
    #   4 DCC, 5 DCD, 6 DDC, 7 DDD
    # A D after our previous D should usually be punished, but empirical
    # data quickly overrides this if they ignore our D.
    prior2 = [0.85, 0.80, 0.72, 0.45, 0.25, 0.30, 0.15, 0.20]
    prior1 = [0.85, 0.72, 0.28, 0.20]

    alpha2 = 2.0
    alpha1 = 3.0
    P = [0.0] * 8

    for s in range(8):
        p2 = (c2[s] + alpha2 * prior2[s]) / (float(tot2[s]) + alpha2)
        s1 = ((s >> 2) << 1) | ((s >> 1) & 1)

        if tot2[s] == 0 and tot1[s1] > 0:
            p1 = (c1[s1] + alpha1 * prior1[s1]) / (float(tot1[s1]) + alpha1)
            p = 0.45 * p2 + 0.55 * p1
        else:
            p = p2

        if p < 0.05:
            p = 0.05
        if p > 0.95:
            p = 0.95
        P[s] = p

    rem = 100 - n
    if rem <= 0:
        return 'D'

    # Finite-horizon expected-value search over the order-2 opponent model.
    prev = [0.0] * 8
    choice = [0] * 8

    for _ in range(rem):
        new = [0.0] * 8

        for s in range(8):
            old_opp = (s >> 1) & 1
            p = P[s]
            q = 1.0 - p

            # If current action is C, next state starts with my=0.
            idxC0 = old_opp
            idxC1 = 2 | old_opp

            # If current action is D, next state starts with my=1.
            idxD0 = 4 | old_opp
            idxD1 = 6 | old_opp

            vC = 3.0 * p + p * prev[idxC0] + q * prev[idxC1]
            vD = (5.0 * p + q) + p * prev[idxD0] + q * prev[idxD1]

            if vC >= vD - 1e-12:
                new[s] = vC
                choice[s] = 0
            else:
                new[s] = vD
                choice[s] = 1

        prev = new

    cur_state = (my[-1] << 2) | (op[-1] << 1) | op[-2]
    action = choice[cur_state]

    # If we still seem completely untested, make a few low-risk probes against
    # cooperative-looking opponents to detect all-C/ignoring behavior.
    if action == 0 and op[-1] == 0 and recent_c_rate > 0.65:
        ownD15 = 0
        for x in my[-15:]:
            if x == 1:
                ownD15 += 1
        if ownD15 <= 2 and totMD < 4:
            if n % 23 == 5 or rng.random() < 0.03:
                action = 1

