def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = []
    op = []
    for pair in history:
        my.append(pair[0])
        op.append(pair[1])

    last_my = my[-1]
    last_op = op[-1]

    opp_c = 0
    for b in op:
        if b == 'C':
            opp_c += 1
    opp_d = n - opp_c

    opp_d_streak = 0
    i = n - 1
    while i >= 0 and op[i] == 'D':
        opp_d_streak += 1
        i -= 1

    start4 = n - 4
    if start4 < 0:
        start4 = 0
    recent4_c = 0
    for j in range(start4, n):
        if op[j] == 'C':
            recent4_c += 1

    forgiven = 0
    punished = 0
    for i in range(1, n):
        if my[i - 1] == 'D':
            if op[i] == 'C':
                forgiven += 1
            else:
                punished += 1

    if opp_c == 0 and opp_d_streak < 4:
        return 'C'

    if opp_d_streak >= 4 and recent4_c == 0:
        return 'D'

    if last_my == 'D' and last_op == 'C' and forgiven == 0 and punished == 0:
        return 'C'

    if last_op == 'C' and n >= 3 and last_my == 'C' and forgiven == 0 and punished == 0:
        db = 0
        j = n - 2
        while j >= 0 and op[j] == 'D':
            db += 1
            j -= 1
        if db >= 2:
            return 'D'

    if forgiven >= 1 and forgiven >= punished and opp_c * 5 >= n * 2:
        if last_op == 'C':
            return 'D'
        if opp_d_streak <= 3:
            return 'D'
        if opp_c * 3 >= n * 2 and last_my == 'C':
            return 'C'
        return 'D'

    if opp_d == 0 and forgiven == 0 and punished == 0 and last_op == 'C':
        if n == 15 or n == 35 or n == 55 or n == 75:
            return 'D'

    if last_op == 'C':
        return 'C'

    if opp_c * 2 >= n and opp_d_streak <= 3:
        return 'C'

    if last_my == 'D' and opp_c * 3 >= n * 2 and opp_d_streak <= 3:
        return 'C'

    if recent4_c >= 1 and opp_d_streak <= 4:
        return 'C'

    if opp_d * 2 >= n:
        return 'D'

    if opp_d * 3 >= n:
        return 'D'

    return 'C'

