    after_c_c = 0
    after_d = 0
    after_d_c = 0
    for i in range(start, n):
        if my[i - 1] == 'C':
            after_c += 1
            if op[i] == 'C':
                after_c_c += 1
        else:
            after_d += 1
            if op[i] == 'C':
                after_d_c += 1

    success_rate = after_c_c / after_c if after_c > 0 else recent_c_rate
    forgive_rate = after_d_c / after_d if after_d > 0 else 0.0
    exploitable = (
