def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    total_d = opp.count('D')

    od = 0
    i = n - 1
    while i >= 0 and opp[i] == 'D':
        od += 1
        i -= 1

    md = 0
    i = n - 1
    while i >= 0 and me[i] == 'D':
        md += 1
        i -= 1

    r5d = opp[-5:].count('D')
    r8d = opp[-8:].count('D')
    r10d = opp[-10:].count('D')

    last_m, last_o = history[-1]

    if last_o == 'C':
        return 'C'

    if last_m == 'C':
        if n >= 2 and me[-2] == 'D' and opp[-2] == 'C' and od <= 2:
            return 'C'

        threshold = n // 5 + 1
        if (
            n >= 8
            and total_d <= threshold
            and r10d <= 2
            and r5d <= 2
            and od <= 1
        ):
            return 'C'

        return 'D'

    if md < 2:
        return 'D'

    if od >= 6:
        return 'D'

    if r8d >= 6 and od >= 3:
        return 'D'

    if r10d >= 8:
        return 'D'

    if total_d * 4 > n * 3:
        return 'D'

    return 'C'

