        if p[1] == 'C':
            opp_c_total += 1

    wlen = n if n < 12 else 12
    opp_c_recent = 0
    for p in history[-wlen:]:
        if p[1] == 'C':
            opp_c_recent += 1
    base = (opp_c_recent + 1.0) / (wlen + 2.0)

    ac_c = 0
    ac_t = 0
    ad_c = 0
    ad_t = 0
    for i in range(1, n):
        age = n - 1 - i
        if age >= 30:
            continue
        if age < 5:
            w = 4
        elif age < 15:
            w = 2
        else:
            w = 1

        prev_me = history[i - 1][0]
        cur_opp = history[i][1]
