            ac_t += w
            if cur_opp == 'C':
                ac_c += w
        else:
            ad_t += w
            if cur_opp == 'C':
                ad_c += w

    ac_d = ac_t - ac_c
    ad_d = ad_t - ad_c
    total_t = ac_t + ad_t

    if total_t > 0:
        match = (ac_c + ad_d) / (total_t + 1.0)
    else:
        match = 0.0
    if match > 1.0:
        match = 1.0
    if match < 0.0:
        match = 0.0

    pc = (ac_c + 2.0 * base + 0.5) / (ac_t + 3.0)
    if pc > 1.0:
        pc = 1.0
    if pc < 0.0:
