def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    if n < 3:
        return 'C'

    last_my, last_opp = history[-1]

    opp_D = 0
    opp_C = 0
    my_D = 0
    for a, b in history:
        if b == 'D':
            opp_D += 1
        else:
            opp_C += 1
        if a == 'D':
            my_D += 1

    opp_D_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        opp_D_streak += 1
        i -= 1

    opp_C_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'C':
        opp_C_streak += 1
        i -= 1

    unprovoked_D_streak = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'C' and history[i][1] == 'D':
        unprovoked_D_streak += 1
        i -= 1

    punish = 0
    forgive = 0
    for i in range(n - 1):
        prev_my = history[i][0]
        next_opp = history[i + 1][1]
        if prev_my == 'D':
            if next_opp == 'D':
                punish += 1
            else:
                forgive += 1

    d_total = punish + forgive

    if opp_C == 0:
        return 'D' if n >= 7 else 'C'

    retaliatory = punish > forgive

    if opp_D == 0:
        if my_D == 0 and opp_C_streak >= 10 and (opp_C_streak % 10 != 1):
            return 'C'
        if last_my == 'D' and d_total == 0:
            return 'C'
        return 'D'

    if last_opp == 'D':
        if unprovoked_D_streak >= 4:
            return 'D'
        if opp_D_streak >= 5 and opp_D * 5 >= n * 3:
            return 'D'
        if n >= 90:
            return 'D'
        return 'C'

    if last_my == 'D' and d_total == 0:
        return 'C'

    if retaliatory:
        if (
            punish == 1
            and opp_C_streak >= 15
            and n >= 20
            and n <= 80
            and opp_D * 5 <= n
        ):
            return 'D'
        return 'C'

    return 'D'

