def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_c = 0
    for _, o in history:
        if o == 'C':
            opp_c += 1
    opp_d = n - opp_c

    d_streak = 0
    for _, o in reversed(history):
        if o == 'D':
            d_streak += 1
        else:
            break

    start = n - 10
    if start < 0:
        start = 0
    rec_d = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            rec_d += 1

    if opp_c == 0:
        return 'D'
    if d_streak >= 5:
        return 'D'
    if opp_d > opp_c:
        return 'D'
    if rec_d >= 7:
        return 'D'

    tft_like = False
    if n >= 5:
        t = 0
        for i in range(1, n):
            if history[i][1] == history[i - 1][0]:
                t += 1
        if t * 5 >= (n - 1) * 3:
            tft_like = True

    if n >= 5 and opp_d * 2 >= n and not tft_like:
        return 'D'

    if n >= 50 and last_opp == 'C' and opp_d == 0:
        return 'D'

    return 'C'

