    if defects_last5_op == 0:
        if n == 99:
            return 'D'
        return 'C'
    if op_defects > 0 and op_defects * 2 < n:
        if op[-1] == 'D':
            return 'D'
        if n % 10 == 9:
            return 'D'
        return 'C'
    if op[-1] == 'D':
        return 'D'
    return 'C'
