def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 3:
        return 'C'

    opp_c = 0
    my_d = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'D':
            my_d += 1

    last_me, last_opp = history[-1]

    recent = 20 if n > 20 else n
    start = n - recent
    recent_opp_c = 0
    for i in range(start, n):
        if history[i][1] == 'C':
            recent_opp_c += 1

    if last_opp == 'D':
        if opp_c == 0:
            return 'D'

        unprov = 0
        my_c_trans = 0
        for i in range(1, n):
            if history[i - 1][0] == 'C':
                my_c_trans += 1
                if history[i][1] == 'D':
                    unprov += 1

        if my_c_trans >= 12 and unprov * 3 > my_c_trans:
            return 'D'

        if last_me == 'C':
            w5 = 5 if n >= 5 else n
            c5 = 0
            for i in range(n - w5, n):
                if history[i][1] == 'C':
                    c5 += 1
            if c5 == 0 and n >= 12 and opp_c * 2 < n:
                return 'D'

    if my_d == 0 and last_opp == 'C' and n >= 40 and recent_opp_c >= 18 and opp_c * 4 > n * 3:
        return 'D'

    counts_c = [6.0, 5.0, 0.0, 0.0]
    counts_t = [6.0, 6.0, 0.25, 0.25]
    recent_trans = n - 35
    if recent_trans < 1:
        recent_trans = 1

    for i in range(1, n):
        pa, pb = history[i - 1]
        s = (2 if pa == 'D' else 0) + (1 if pb == 'D' else 0)
        w = 1.0 if i >= recent_trans else 0.5
        counts_t[s] += w
        if history[i][1] == 'C':
            counts_c[s] += w

    p = [0.0, 0.0, 0.0, 0.0]
    for s in range(4):
        v = counts_c[s] / counts_t[s]
        if v < 0.0:
            v = 0.0
        elif v > 1.0:
            v = 1.0
        p[s] = v

    cur_state = (2 if last_me == 'D' else 0) + (1 if last_opp == 'D' else 0)
    rem = 100 - n
    prev = [0.0, 0.0, 0.0, 0.0]
    act = 0

    for t in range(1, rem + 1):
        cur = [0.0, 0.0, 0.0, 0.0]
        for s in range(4):
            ps = p[s]
            q = 1.0 - ps

            cval = 3.0 * ps + ps * prev[0] + q * prev[1]
            dval = 1.0 + 4.0 * ps + ps * prev[2] + q * prev[3]

            if dval > cval + 0.02:
                cur[s] = dval
                if t == rem and s == cur_state:
                    act = 1
            else:
                cur[s] = cval
                if t == rem and s == cur_state:
                    act = 0

        prev = cur

    if act:
        return 'D'
    return 'C'

