def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'

    my = []
    op = []
    op_c = 0
    for pair in history:
        a = pair[0]
        b = pair[1]
        if a == 'C':
            my.append(0)
        else:
            my.append(1)
        if b == 'C':
            op.append(0)
            op_c += 1
        else:
            op.append(1)

    h = 100 - n
    if h <= 0:
        return 'D'
    if h == 1:
        return 'D'

    if n >= 3 and op_c == 0:
        return 'D'
    if n >= 8 and op_c <= 1:
        return 'D'

    rstart = n - 15
    if rstart < 0:
        rstart = 0
    recent_c = 0
    for i in range(rstart, n):
        if op[i] == 0:
            recent_c += 1
    recent_len = n - rstart
    recent_rate = float(recent_c) / float(recent_len)
    overall_rate = float(op_c) / float(n)
    w = 0.45 * overall_rate + 0.55 * recent_rate

    opp_D_run = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 1:
            opp_D_run += 1
        else:
            break

    dd_run = 0
    for i in range(n - 1, -1, -1):
        if my[i] == 1 and op[i] == 1:
            dd_run += 1
        else:
            break

    failed = 0
    for i in range(1, n):
        if my[i - 1] == 1 and op[i - 1] == 1 and my[i] == 0 and op[i] == 1:
            failed += 1

    just_attempted = False
    if n >= 2 and my[-1] == 0 and op[-1] == 1 and my[-2] == 1 and op[-2] == 1:
        just_attempted = True

    if just_attempted and h > 2:
        return 'C'

    if 2 <= opp_D_run <= 3 and w > 0.50 and h > 3:
        return 'D'

    if opp_D_run >= 4 and opp_D_run <= 7 and op_c >= 4 and w > 0.55 and failed == 0 and h > 3:
        return 'C'

    num = [0, 0, 0, 0]
    den = [0, 0, 0, 0]
    for i in range(1, n):
        st = my[i - 1] * 2 + op[i - 1]
        den[st] += 1
        if op[i] == 0:
            num[st] += 1

    prior = [0.0, 0.0, 0.0, 0.0]
    prior[0] = 0.92 + 0.07 * w
    prior[1] = 0.26 + 0.66 * w
    prior[2] = 0.02 + 0.10 * w
    prior[3] = 0.04 + 0.16 * w

    if w > 0.55:
        if opp_D_run >= 2:
            prior[1] += 0.06
            prior[3] -= 0.03
        if opp_D_run >= 4:
            prior[1] += 0.08
            prior[3] -= 0.05
    else:
        if prior[1] > 0.40:
            prior[1] = 0.40
        if prior[3] > 0.15:
            prior[3] = 0.15

    for st in range(4):
        if prior[st] < 0.02:
            prior[st] = 0.02
        if prior[st] > 0.97:
            prior[st] = 0.97

    pseudo = 2.0
    p = [0.0, 0.0, 0.0, 0.0]
    for st in range(4):
        p[st] = float(num[st] + pseudo * prior[st]) / float(den[st] + pseudo)

    prev = [0.0, 0.0, 0.0, 0.0]
    for _ in range(h - 1):
        cur = [0.0, 0.0, 0.0, 0.0]
        for s in range(4):
            pc = p[s]
            q = 1.0 - pc
            vC = pc * (3.0 + prev[0]) + q * (0.0 + prev[1])
            vD = pc * (5.0 + prev[2]) + q * (1.0 + prev[3])
            if vC >= vD - 1e-9:
                cur[s] = vC
            else:
                cur[s] = vD
        prev = cur

    st = my[-1] * 2 + op[-1]
    pc = p[st]
    q = 1.0 - pc
    vC = pc * (3.0 + prev[0]) + q * (0.0 + prev[1])
    vD = pc * (5.0 + prev[2]) + q * (1.0 + prev[3])

    if vC >= vD - 1e-9:
        return 'C'
    return 'D'

