    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_d = 0
    my_d = 0
    unprov = 0
    recent_len = 10
    recent_d = 0
    recent_c = 0

    for i in range(n):
        me, op = history[i]
        if op == 'D':
            opp_d += 1
        if me == 'D':
            my_d += 1

        if i >= n - recent_len:
            if op == 'D':
                recent_d += 1
            else:
                recent_c += 1

        if i == 0:
            if op == 'D':
                unprov += 1
        else:
            if op == 'D' and history[i - 1][0] == 'C':
