        return 'C'

    if last_my == 'D' and opp_d_streak >= 3 and recent5_opp_c >= 1:
        return 'C'

    if opp_d_streak >= 2:
        return 'D'

    if recent3_opp_c >= 1:
        return 'C'

    if recent10_opp_c >= 2:
        return 'C'

    return 'D'

