    if n == 0:
        return 'C'
    if n < 3:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_c = 0
    opp_d = 0
    recent10_c = 0
    limit10 = n - 10
    for i, pair in enumerate(history):
        if pair[1] == 'D':
            opp_d += 1
        else:
            opp_c += 1
            if i >= limit10:
                recent10_c += 1

    opp_d_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        opp_d_streak += 1
        i -= 1

    mutual_d_streak = 0
    i = n - 1
    while i >= 0:
        if history[i][0] == 'D' and history[i][1] == 'D':
            mutual_d_streak += 1
            i -= 1
        else:
            break

    dc_c = 0
    dc_d = 0
    start = n - 20
    if start < 0:
        start = 0
    near = n - 5
    if near < 0:
        near = 0
    for i in range(start, n - 1):
        if history[i][0] == 'D' and history[i][1] == 'C':
            w = 2 if i >= near else 1
            if history[i + 1][1] == 'C':
                dc_c += w
            else:
                dc_d += w

    forgiving = dc_c > dc_d and dc_c >= 2

    if opp_c == 0:
        return 'D'

    if opp_d_streak >= 8 or mutual_d_streak >= 8 or opp_d > opp_c + 10:
        return 'D'

    if opp_last == 'D':
        if my_last == 'D':
            return 'C'
        if history[-2][0] == 'D':
            return 'C'
        return 'D'

    if my_last == 'D':
        if forgiving:
            return 'D'
        return 'C'

    if forgiving:
        return 'D'

    p = 0.0
    if recent10_c >= 8 and n >= 20 and dc_d <= dc_c:
        if opp_d == 0:
            if n >= 85:
                p = 0.10
            elif n >= 50:
                p = 0.03
            else:
                p = 0.01
        elif opp_c > opp_d + 5:
            if n >= 85:
                p = 0.05
            elif n >= 60:
                p = 0.015
            else:
                p = 0.002

    if p > 0.0 and rng.random() < p:
        return 'D'

    return 'C'

