def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Final round: defect is strictly best when there is no future cost.
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_c = 0
    opp_d = 0
    my_c = 0
    my_d = 0
    inv_mimic = 0

    for i in range(n):
        a = history[i][0]
        b = history[i][1]

        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1

        if a == 'C':
            my_c += 1
        else:
            my_d += 1

        if i > 0:
            prev_a = history[i - 1][0]
            if b != prev_a:
                inv_mimic += 1

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    opp_c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            opp_c_streak += 1
        else:
            break

    my_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_d_streak += 1
        else:
            break

    my_c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C':
            my_c_streak += 1
        else:
            break

    s = 5 if n >= 5 else n
    short_opp_c = 0
    short_opp_d = 0
    short_my_c = 0
    for i in range(n - s, n):
        if history[i][1] == 'C':
            short_opp_c += 1
        else:
            short_opp_d += 1
        if history[i][0] == 'C':
            short_my_c += 1

    k = 8 if n >= 8 else n
    med_opp_c = 0
    med_opp_d = 0
    med_my_c = 0
    for i in range(n - k, n):
        if history[i][1] == 'C':
            med_opp_c += 1
        else:
            med_opp_d += 1
        if history[i][0] == 'C':
            med_my_c += 1

    opp_changes = 0
    if k >= 2:
        for i in range(n - k + 1, n):
            if history[i][1] != history[i - 1][1]:
                opp_changes += 1

    # Detect the controlled periodic_D pattern: two Ds then three Cs, repeatedly.
    periodic = False
    if n >= 10:
        L = 12 if n >= 12 else n
        start = n - L
        opp_d_l = 0
        for i in range(start, n):
            if history[i][1] == 'D':
                opp_d_l += 1

        if 2 <= opp_d_l <= L - 2:
            best = 0
            for phase in range(5):
                matches = 0
                for idx in range(L):
                    ch = history[start + idx][1]
                    if (idx + phase) % 5 < 2:
                        if ch == 'D':
