        if prev_my_was_D and opp_rate > 0.45 and recent_rate > 0.35 and recent_my_rate > 0.40 and trail_opp_d <= 4:
            if rng.random() < 0.60:
                return 'C'
        return 'D'
    if s_cur == 0:
        if pD[2] > 0.58 or (pD[2] > 0.45 and rD_blend > 0.60):
            action = 'C'
            if unprovoked == 0 and my_rate > 0.80 and opp_rate > 0.87 and recent_rate > 0.85 and n < 55:
