            elif unprovoked == 0 and my_rate > 0.70 and opp_rate > 0.80 and recent_rate > 0.78 and n < 85:
                if rng.random() < 0.004:
                    action = 'D'
            return action
    if s_cur == 3 and action == 'D':
        if opp_rate > 0.45 and recent_my_rate > 0.35 and mutual_d < 6:
            if rng.random() < 0.50 + 0.40 * opp_rate:
                return 'C'
        if opp_rate > 0.60 and recent_rate > 0.35 and trail_opp_d <= 3:
            if rng.random() < 0.45:
                return 'C'
    if s_cur == 2 and action == 'D' and unprovoked == 0 and n < 25 and pD[2] > 0.30:
        return 'C'
    return action

