def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'
    rem = 100 - n

    me = [0] * n
    op = [0] * n
    all_d = True
    for i in range(n):
        if history[i][0] == 'C':
            me[i] = 0
        else:
            me[i] = 1
        if history[i][1] == 'C':
            op[i] = 0
        else:
            op[i] = 1
        if op[i] == 0:
            all_d = False

    if all_d:
        return 'D'

    start = n - 6
    if start < 0:
        start = 0
    recent_c = 0
    recent_len = n - start
    for i in range(start, n):
        if op[i] == 0:
            recent_c += 1

    if recent_c == 0:
        return 'D'

    last_me = me[n - 1]
    last_op = op[n - 1]

    if n >= 99:
        return 'D'

    cd_run = 0
    i = n - 1
    while i >= 0:
        if me[i] == 0 and op[i] == 1:
            cd_run += 1
            i -= 1
        else:
            break

    opp_d_run = 0
    i = n - 1
    while i >= 0:
        if op[i] == 1:
            opp_d_run += 1
            i -= 1
        else:
            break

    if cd_run >= 2:
        return 'D'

    if cd_run == 1:
        if recent_c >= 3:
            return 'C'
        if n >= 2 and me[n - 2] == 1 and op[n - 2] == 1:
            return 'C'
        return 'D'

    if opp_d_run >= 3 and last_me == 1 and last_op == 1 and recent_c > 0:
        return 'C'

    if n < 10:
        return 'C'

    op_c = n - sum(op)

    if (n >= 25 and n <= 90 and recent_c == recent_len and
            last_me == 0 and last_op == 0 and op_c * 5 >= n * 4):
        if rng.random() < 0.006:
            return 'D'

    counts_c = [0.0, 0.0, 0.0, 0.0]
    counts_tot = [0.0, 0.0, 0.0, 0.0]
    prior = [0.95, 0.85, 0.10, 0.45]
    pseudo = 4.0

    for i in range(n - 1):
        idx = me[i] * 2 + op[i]
        w = 1.0
        if n - 1 - i > 20:
            w = 0.3
        counts_tot[idx] += w
        if op[i + 1] == 0:
            counts_c[idx] += w

    probs = [0.0, 0.0, 0.0, 0.0]
    for idx in range(4):
        probs[idx] = (counts_c[idx] + pseudo * prior[idx]) / (counts_tot[idx] + pseudo)
        if probs[idx] < 0.01:
            probs[idx] = 0.01
        if probs[idx] > 0.99:
            probs[idx] = 0.99

    if (counts_tot[2] >= 2.0 and
            counts_c[2] > counts_tot[2] - 0.5 and
            last_op == 0 and
            recent_c >= 2):
        return 'D'

    if (rem > 20 and last_me == 0 and last_op == 0 and
            recent_c == recent_len and op_c * 5 >= n * 4):
        return 'C'

    vals = [[0.0, 0.0, 0.0, 0.0]]
    for d in range(1, rem + 1):
        prev = vals[d - 1]
        cur = [0.0, 0.0, 0.0, 0.0]
        for s in range(4):
            pc = probs[s]
            npc = 1.0 - pc
            val_c = pc * (3.0 + prev[0]) + npc * prev[1]
            val_d = pc * (5.0 + prev[2]) + npc * (1.0 + prev[3])
            if val_c > val_d:
                cur[s] = val_c
            else:
                cur[s] = val_d
        vals.append(cur)

    state = last_me * 2 + last_op
    prev = vals[rem - 1]
    pc = probs[state]
    npc = 1.0 - pc
    val_c = pc * (3.0 + prev[0]) + npc * prev[1]
    val_d = pc * (5.0 + prev[2]) + npc * (1.0 + prev[3])

    if val_c >= val_d:
        return 'C'
    return 'D'

