def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_c = 0
    opp_d = 0
    my_d = 0
    rec_opp_c = 0
    last_me, last_opp = history[-1]
    w = 8 if n > 8 else n

    for i in range(n):
        a, b = history[i]
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if a == 'D':
            my_d += 1
        if n - i <= w and b == 'C':
            rec_opp_c += 1

    after_c_c = 0
    after_c_d = 0
    after_d_c = 0
    after_d_d = 0
    for i in range(n - 1):
        prev = history[i][0]
        nxt = history[i + 1][1]
        if prev == 'C':
            if nxt == 'C':
                after_c_c += 1
            else:
                after_c_d += 1
        else:
            if nxt == 'C':
                after_d_c += 1
            else:
                after_d_d += 1

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    if opp_c == 0:
        return 'D'

    if opp_d == 0:
        if my_d > 0 or n >= 90:
            return 'D'
        return 'C'

    if rec_opp_c == 0 and opp_c * 3 <= n:
        return 'D'

    total_d_react = after_d_c + after_d_d
    pushover = total_d_react >= 3 and after_d_c * 2 > after_d_d

    if last_opp == 'D':
        if last_me == 'C':
            delayed = n >= 2 and history[-2][0] == 'D'
            if delayed and opp_c * 2 >= n and rec_opp_c >= 2 and opp_d_streak <= 4:
                return 'C'
            if delayed and opp_c * 2 >= n and rec_opp_c >= 2 and opp_d_streak <= 2 and after_d_d >= after_d_c:
                return 'C'
            if my_d > opp_d + 2 and opp_d * 2 < n and rec_opp_c >= 2:
                return 'C'
            if opp_c * 3 >= n and rec_opp_c >= 5 and opp_d_streak <= 1 and rng.random() < 0.1:
                return 'C'
            return 'D'
        else:
            if opp_c * 3 >= n and rec_opp_c >= 2 and opp_d_streak <= 5:
                return 'C'
            if opp_c * 2 >= n and rec_opp_c >= 2 and opp_d_streak <= 3:
                return 'C'
            if opp_c * 3 >= n and opp_d_streak <= 3 and rng.random() < 0.07:
                return 'C'
            return 'D'
    else:
        if last_me == 'D':
            if pushover:
                return 'D'
            return 'C'
        else:
            if pushover and n >= 80 and opp_c * 5 >= 4 * n:
                return 'D'
            return 'C'

